import React from 'react';
import LoginForm from './LoginForm';
import AppMain from './AppMain';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<LoginForm />} />
        <Route path="/main" element={<AppMain />} />
      </Routes>
    </Router>
  );
}

export default App;
